#!/usr/bin/env python
"""S12c: append an auto-generated section to RESULTS.md with the full-record timing (summary_full.csv) and the echo
amplitude / similarity stage (amp_full_*.csv). Numbers only; plain-words reading is added by hand afterwards."""
import glob, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import numpy as np, pandas as pd
from acf_common import WS
L = ["", f"## Full record 2003–2026 — AUTO-GENERATED by scripts/acf06_report.py "
         f"({pd.Timestamp.now(tz='America/Los_Angeles'):%a %Y-%m-%d %H:%M} PT); reading to be added", ""]
if os.path.exists(f"{WS}/tables/summary_full.csv"):
    S = pd.read_csv(f"{WS}/tables/summary_full.csv")
    S = S[S.bin == "post0_15"]
    L += ["### Timing, days 0–15 vs −30…−1 (Δt ms; σ robust scrambled; pct one-sided, Vs-increase direction)", "",
          "| station | band | mask | phase | Δt | σ | pct | control | target |", "|---|---|---|---|---|---|---|---|---|"]
    for _, r in S.iterrows():
        L.append(f"| {r.station} | {r.band} | {r['mask']} | {r.phase} | {r.ddt_ms:+.1f} | {r.scr_rsd_ms:.1f} | {r.pct_neg:.3f} | "
                 f"{r.ctl_ms:+.1f} | {r.target_ms:.0f} |")
    for f in sorted(glob.glob(f"{WS}/tables/recovery_fit_full_*.csv")):
        F = pd.read_csv(f); L += ["", f"Recovery fits {os.path.basename(f)} (meaningful only where P3 passes): " +
                                  "; ".join(f"{r.band} {r.phase}: A {r.A_ms:+.1f} ms, τ {r.tau_d:.0f} d" for _, r in F.iterrows())]
rows = []
for f in sorted(glob.glob(f"{WS}/tables/amp_full_*.csv")):
    p = os.path.basename(f)[:-4].split("_"); ns, band, mask = p[-4], p[-3] + "_" + p[-2], p[-1]
    T = pd.read_csv(f)
    for ph in ["SS", "PS", "PP"]:
        for bn in ["post0_15", "post15_30", "post30_60"]:
            g = T[(T.pair == ph) & (T.bin == bn)].set_index("metric")
            if "A_top" not in g.index: continue
            d = dict(station=ns, band=band, mask=mask, phase=ph, bin=bn)
            for q in ["A_top", "A_bottom", "cc_top", "cc_bottom", "rms_top", "rms_bottom"]:
                d[q] = g.loc[q, "obs"]; d[q + "_rsd"] = g.loc[q, "scr_rsd"]; d[q + "_pct2"] = g.loc[q, "pct_two"]
            rows.append(d)
if rows:
    A = pd.DataFrame(rows); A.to_csv(f"{WS}/tables/amp_summary_full.csv", index=False)
    a = A[A.bin == "post0_15"]
    L += ["", "### Echo strength and similarity, days 0–15 vs −30…−1 (PLAN amendment B)",
          "A = relative echo strength change (projection on the long-term echo, divided by the same for the window above",
          "the LVL), in %; CC = change of CC with the long-term echo; σ robust scrambled; p2 = two-sided scrambled pct.", "",
          "| station | band | mask | phase | A top % (σ, p2) | A bottom % (σ, p2) | CC top (σ, p2) | CC bottom (σ, p2) |",
          "|---|---|---|---|---|---|---|---|"]
    for _, r in a.iterrows():
        f = lambda q, s=100: f"{s * r[q]:+.1f} ({s * r[q + '_rsd']:.1f}, {r[q + '_pct2']:.3f})"
        g = lambda q: f"{r[q]:+.3f} ({r[q + '_rsd']:.3f}, {r[q + '_pct2']:.3f})"
        L.append(f"| {r.station} | {r.band} | {r['mask']} | {r.phase} | {f('A_top')} | {f('A_bottom')} | {g('cc_top')} | {g('cc_bottom')} |")
    L += ["", "Figures: `figures/amp_full_<STA>_<band>_<mask>.png`, `figures/compare_rf_full_<STA>.png`, "
          "`figures/epoch_full_*.png`."]
open(f"{WS}/RESULTS.md", "a").write("\n".join(L) + "\n")
print("\n".join(L))
